      "fact": "A single blue line connects six points, one for each year from 2018 to 2023."
    },
    {
      "location": "left side of chart",
      "fact": "The line begins at the 2018 mark at a vertical position aligned with the 2,800 tick."
    },
    {
      "location": "left-center of chart",
      "fact": "The line drops to its lowest vertical position at the 2019 mark, aligned with the 2,400 tick."
    },
    {
      "location": "center of chart",
      "fact": "The line rises to its highest vertical position at the 2020 mark, slightly above the 2,800 tick."
    },
    {
      "location": "right side of chart",
      "fact": "From 2021 to 2023, the line remains nearly horizontal at a vertical position between the 2,400 and 2,800 ticks, slightly lower than the 2018 starting point."
    },
    {
      "location": "entire chart",
      "fact": "The line fluctuates within a narrow band between the 2,400 and 2,800 grid lines for the entire duration."
    }
  ],
  "printed_facts": [
    {
      "location": "top center",
      "fact": "Title reads: 'Increasing Clean Grid Output from 2018 to 2023'."
    },
    {
      "location": "left axis",
      "fact": "Y-axis is labeled 'Grid Output (GWh)' with ticks at 0, 400, 800, 1,200, 1,600, 2,000, 2,400, and 2,800."
    },
    {
      "location": "bottom axis",
      "fact": "X-axis is labeled 'Year' with ticks for 2018, 2019, 2020, 2021, 2022, and 2023."
    }
  ],
